const S2 = "organizacion-procedimiento-trabajo";
console.log(`📝 flashcards (${S2})...`);
await insertar("flashcards", [
  { anverso: "¿Qué es la organización del trabajo, en el contexto del mantenimiento diario de un cementerio?", reverso: "La planificación y distribución ordenada de las tareas a realizar, los recursos necesarios y el personal disponible, con el fin de atender de forma eficiente las necesidades del recinto (mantenimiento, reparaciones, inhumaciones programadas) dentro de los plazos previstos" },
  { anverso: "¿Por qué la planificación previa del trabajo diario resulta especialmente relevante en un cementerio, frente a otros entornos de mantenimiento menos condicionados por horarios externos?", reverso: "Porque las inhumaciones y otros actos programados tienen horarios fijados de antemano que no admiten demora, por lo que la planificación debe garantizar que los recursos y el personal necesarios estén disponibles en el momento exacto requerido" },
  { anverso: "¿Qué es un procedimiento de trabajo, frente a una simple instrucción verbal puntual?", reverso: "Una secuencia ordenada y documentada de pasos a seguir para realizar una tarea concreta de forma sistemática, que garantiza un resultado homogéneo con independencia de quién la ejecute, a diferencia de una instrucción verbal puntual, que depende de la comunicación en cada ocasión concreta" },
  { anverso: "¿Por qué la coordinación entre distintos oficios (albañilería, jardinería, mantenimiento eléctrico) resulta relevante en la organización del trabajo de un cementerio?", reverso: "Porque muchas tareas dependen de la actuación previa o simultánea de varios oficios distintos, y una falta de coordinación puede generar retrasos, duplicidad de esfuerzos o incluso interferencias entre trabajos que deberían complementarse" },
  { anverso: "¿Qué es la priorización de tareas, como parte de la organización diaria del trabajo, y por qué resulta necesaria cuando los recursos disponibles son limitados?", reverso: "El criterio empleado para decidir el orden en que se abordan las distintas tareas pendientes según su urgencia o importancia relativa, necesaria porque los recursos de personal y tiempo son limitados y no todas las tareas pueden atenderse simultáneamente" },
  { anverso: "¿Por qué una avería detectada en un elemento de riesgo inmediato (por ejemplo, un dintel con signos de colapso) debe priorizarse frente a una tarea de mantenimiento rutinario, aunque esta última estuviera ya planificada previamente?", reverso: "Porque un riesgo inmediato para la seguridad de las personas debe atenderse antes que cualquier tarea de mantenimiento programada sin urgencia real, ya que las consecuencias de no actuar a tiempo pueden ser mucho más graves que el retraso de una tarea rutinaria" },
  { anverso: "¿Qué es un parte de trabajo (o registro de incidencias), y para qué resulta útil en la organización del trabajo diario?", reverso: "Un documento donde se anota la tarea realizada, el tiempo empleado, los materiales utilizados o las incidencias detectadas, útil para llevar un control de lo ejecutado, planificar tareas futuras y disponer de un histórico consultable del mantenimiento del recinto" },
  { anverso: "¿Por qué la comunicación fluida entre el oficial y su responsable directo resulta relevante para una organización del trabajo eficaz?", reverso: "Porque permite ajustar la planificación diaria ante imprevistos (una inhumación adicional, una avería urgente) y transmitir información relevante detectada en el trabajo diario que puede afectar a la planificación de tareas futuras" },
  { anverso: "¿Por qué el procedimiento de trabajo debe revisarse y actualizarse periódicamente, en lugar de mantenerse invariable indefinidamente una vez establecido?", reverso: "Porque las condiciones del trabajo pueden cambiar (nuevos equipos, nueva normativa, lecciones aprendidas de incidencias pasadas), y un procedimiento no actualizado puede quedar desfasado respecto a la forma más eficiente o segura de realizar la tarea en cada momento" },
  { anverso: "¿Por qué es relevante que el oficial de cementerio comprenda los principios generales de organización del trabajo, más allá de ejecutar las tareas concretas que se le asignan?", reverso: "Porque comprender esos principios permite anticipar necesidades, proponer mejoras en la planificación diaria y adaptarse con criterio a situaciones imprevistas, en lugar de limitarse a esperar instrucciones puntuales para cada nueva tarea que surja" },
].map((f) => ({ ...f, tema_slug: TEMA, seccion: S2 })));

